INSERT INTO `aspirantes_fps` (`id`, `apellido`, `nombre`, `dni`, `password`, `fechnaci`, `lugarnac`, `sexo`, `domicilio`, `barrio`, `telefono`, `madpad`, `nombremad`, `telemad`, `emailmad`, `nombrepad`, `telepad`, `emailpad`, `nombretut`, `teletut`, `emailtut`, `escori`, `destino`, `obs`, `fechhora`, `identif`, `idnivel`, `hijoherm`, `dathijo`, `datherm`, `needes`, `needes_detalle`, `vivecon`, `parroquia`, `motivo`, `motivo_detalle`, `acopro`, `acopro_detalle`, `idAspiTerlec`, `tipoinscri`, `hermanosAspirantes`) VALUES
	(1, 'Sebastian ', 'Lara Manuela ', '50996353', '2122', '2011-07-10', 'Córdoba Capital ', 'Femenino', 'Mar de Ajo 538', 'Parque Horizonte ', '3517013303', 'Madre', '', '', '', 'Laura Verónica Olmos ', '3517013303', 'lauraveronicaolmos85@gmail.com', '', '', '', 'Escuela Manuel Belgrano ', 'Primer Año (Secundario)', '', '2023-08-16 00:16:16', '2580025951', 3, 0, '*', '*', 'No', '*', 'Madre, Padre, Hermana', 'Capilla Virgen Niña', 'Referido', 'Leonor Moreno', 'No', '*', 11, 2, ''),
	(8, 'Andrada ', 'Bruna Emilia ', '55838703', 'Brunae2016', '2016-10-20', 'Córdoba ', 'Femenino', 'La Cumbre 5903', 'Comercial ', '3516085951', 'Madre', '', '', '', 'Laura Celeste López ', '3516085951', 'acsceleste@gmail.com', '', '', '', 'Escuela provincia de Catamarca ', 'Segundo Grado (Primario  - Solo turno tarde) ', '', '2023-08-16 06:51:34', '5016193459', 2, 0, '*', '*', 'No', '*', 'Mamá, papá, y hermanos ', 'Jesucristo Salvador del mundo ', 'Es hermano de un alumno actual del Colegio', 'Candela Abril Andrada 4°D secundaria ', 'No', '*', 11, 2, ''),
	(2, 'Barraquero Zarate', 'Morena Lucía', '49586639', 'Episte23', '2009-08-07', 'Córdoba, Argentina', 'Femenino', 'Publica 19. N° 4285', 'Carrara de Horizonte', '3516899169', 'Madre', '', '', '', 'Natalia, Zarate Soruco', '3516899169', 'nataliazarate29@gmail.com', '', '', '', 'Centro Educativo Cristo Rey', 'Tercero Año (Secundario)', '', '2023-08-16 00:19:53', '5798697752', 3, 0, '*', '*', 'No', '*', 'Madre  y Padre', 'Parroquia Cristo Rey', 'Otros', 'Elegimos postular a nuestra hija a una vacante en la institución en primer lugar porque sigue la misma línea, que el Centro Educativo Cristo Rey al cual asiste actualmente, en cuanto a la educación comprometida, comunitaria y cristiana. \r\nPero necesitamos cambiar debido a que nos mudamos de casa y por cuestiones de distancia nos quedaría mejor en cuanto a tiempos y organización familiar el colegio parroquial San Francisco de Asís. Además, pensando en el ciclo orientado nos interesa la propuesta de la institución, particularmente Ciencias Sociales. ', 'No', '*', 11, 2, ''),
	(3, 'Nievas Meloni', 'Fabricio ', '56761265', 'Fabri265', '2018-01-21', 'Cordoba', 'Masculino', 'Pastor taboada 311', 'Las flores', '3512322393', 'Madre', '', '', '', 'Gisella Melisa Meloni ', '3512322393', 'Meli_meloni@hotmail.com', '', '', '', 'Escuela Syria Poletti ', 'Primer Grado (Primario - Solo turno tarde)', 'Se hizo otro relevamiento por sus hermanos,para 3° grado del primario y 2° año del secundario.\nSería de nuestro agrado que nuestro hijos pueden ingresar al establecimiento.\nMuchas gracias.', '2023-08-16 00:54:20', '7779451280', 2, 0, '*', '*', 'No', '*', 'Con los padres y hermanos', 'San Francisco de Asis', 'Soy vecino/a', '*', 'No', '*', 11, 2, 'Si hermana para 2° del secundario y hermano para 3 grado del primario. '),
	(4, 'Nievas Meloni ', 'Facundo ', '54759878', 'Facu878', '2015-07-24', 'Cordoba', 'Masculino', 'Pastor taboada 311', 'Las flores', '3512322393', 'Madre', '', '', '', 'Gisella Melisa Meloni ', '3512322393', 'meli_meloni@hotmail.com', '', '', '', 'Escuela Syria Poletti ', 'Tercer Grado (Primario  - Solo turno tarde) ', 'Se hizo un relevamiento para sus hermanos,para 1° grado del primario y 2° año del secundario.\nSería de nuestro agrado que nuestro hijos pudieran ingresar al establecimiento,ya que vivimos a 2 cuadras del mismo.\nMuchas gracias.', '2023-08-16 01:05:11', '8262659243', 2, 0, '*', '*', 'No', '*', 'Con los padres y hermanos', 'San Francisco de Asis', 'Soy vecino/a', '*', 'No', '*', 11, 2, 'Si hermana para 2° año del secundario y hermano para 1° grado del primario'),
	(5, 'Loza Meloni ', 'María Pia ', '50331429', 'Pia429', '2010-07-28', 'Cordoba', 'Femenino', 'Pastor taboada 311', 'Las flores', '3512322393', 'Madre', '', '', '', 'Gisella Melisa Meloni ', '3512322393', 'meli_meloni@hotmail.com', '', '', '', 'Ipem n° 195 1° teniente Pedro Ignacio Bean', 'Segundo Año (Secundario)', 'Se realizo un relevamiento por sus hermanos para 1° grado y 3° del primario,Les agradeceríamos de corazón que tuvieran a nuestros hijos en cuenta para el ingreso a su institución. Estamos a 2 cuadras del colegio. Saludamos ante Flia Nievas Meloni. ', '2023-08-16 01:14:01', '1917683762', 3, 0, '*', '*', 'No', '*', 'Con la madre,padrastro y hermanos', 'San Francisco de Asis', 'Soy vecino/a', '*', 'No', '*', 11, 2, 'Si hermano para 1° grado y hermano para 3° grado del primario'),
	(6, 'sanchez paco', 'valentina jazmin ', '56245447', '56245447', '2017-08-10', 'cordoba', 'Femenino', 'popayan 5526', 'villa el libertador', '3513307289', 'Madre', '', '', '', 'mary elena paco colque', '3513307289', 'm_elena04@hotmail.com', '', '', '', 'santa teresa de asis ', 'Primer Grado (Primario - Solo turno tarde)', 'Me gustaria anotarla a vale en en mismo curso de Joaquin Avendaño, porque nos vamos a coordinar con la mamá de joaquin para llevarlos al coleguio y retirarlos semanalmente ', '2023-08-16 02:07:02', '5210559202', 2, 0, '*', '*', 'No', '*', 'con la mamá y papá', 'nuestra señora del trabajo', 'Tengo un familiar en la Institución', 'alumno joaquin avendaño sala 5 jardin. hijo de mi amiga de infancia ', 'No', '*', 11, 2, ''),
	(7, 'Callejo', 'Bautista Nicolás Gadiel', '52156997', 'Callejo11', '2011-11-05', 'Córdoba Capital ', 'Masculino', 'Jose guardado 52', 'Barrio las Flores ', '3517683618', 'Madre', '', '', '', ' Tablada pamela', '3517683618', 'maitetablada11@gmail.com', '-', '-', '-', 'Colegio Alejandro Carbo', 'Primer Año (Secundario)', 'Hola buenos días ,ingresé a la página muy de temprano para ver si lograba anotar a mí hijo Bautista .\nCualquier cosa estoy a su disposición,estamos muy interesados en ests bella institución donde me gustaría muchísimo que mí hijo forme parte de ella . Desde ya muchas gracias!\nBendiciones.\nSaluda atte Pamela Tablada ', '2023-08-16 04:55:17', '5823144197', 3, 0, '*', '*', 'No', '*', 'Mamá y padrastro ', 'Jesuscristo salvador del mundo ', 'Soy vecino/a', '*', 'No', '*', 11, 2, 'No tiene hermanos '),
