	(11, 'Sanchez', 'Araxi Luciana Candela', '52156957', 'A25737981', '2012-03-22', 'cordoba', 'Femenino', 'Consejal F Belardinelli 3950', 'Parque Los Molinos', '3512568780', 'Madre', '', '', '', 'Maria Laura Molina', '3512568780', 'enzoquiro77@gmail.com', '', '', '', 'Gral Juan Butista Bustos', 'Primer Año (Secundario)', '', '2023-08-16 07:57:04', '5855423183', 3, 0, '*', '*', 'No', '*', 'Padres y Hermanos', 'Ntra Sra Del Trabajo', 'Tengo un familiar en la Institución', 'Quiroga Catriel Tio', 'No', '*', 11, 2, ''),
	(12, 'Gener', 'Esmeralda Anahi', '52052311', 'Esmeralda', '2011-12-14', 'Córdoba', 'Femenino', 'Hugo Juárez S/N', 'Smata', '3513687622', 'Madre', '', '', '', 'Analia Laura Navarro', '3512067738', 'analaunavarro@hotmail.com', '', '', '', 'FASTA- Santo Domingo de Guzmán', 'Primer Año (Secundario)', 'Elegimos esta institución no solo por la cercanía a nuestro hogar, sino también por la formación integral que ofrece: académica y basada en principios morales y cristianos. Por ello rogamos  que Esmeralda pueda ingresar a este colegio y continuar en este camino que viene transitando durante toda su escolarización.', '2023-08-16 08:01:12', '4660216512', 3, 0, '*', '*', 'No', '*', 'mamá, papá y hermano mayor', 'Santa Mónica y San Agustín', 'Soy vecino/a', '*', 'No', '*', 11, 2, ''),
	(13, 'Moya', 'Jazmin Ariana', '52227212', 'A26090063', '2012-04-04', 'cordoba', 'Femenino', 'Consejal F Belardinelli 3950', 'Parque Los Molinos', '3513820602', 'Madre', '', '', '', 'Natalia Abigail Molina', '3513820602', 'Natumoll2012@gmail.com', '', '', '', 'Jorge Vocos Lescano', 'Primer Año (Secundario)', '', '2023-08-16 08:08:14', '4613207726', 3, 0, '*', '*', 'No', '*', 'Padres y Hermanos', 'Ntra Sra Del Trabajo', 'Tengo un familiar en la Institución', 'Quiroga Catriel Tio', 'No', '*', 11, 2, ''),
