	(15, 'LUCERO GUZMAN', 'MATIAS EMANUEL ', '48330825', '30148412', '2008-04-11', 'CÓRDOBA CAPITAL ', 'Masculino', 'Calle 3 Mza 3 Lote 14', 'Amp. Santa Rosa', '3518136773', 'Madre', '', '', '', 'Maria Estela LUCERO', '3518136773', 'camymaty84@gmail.com ', 'Ningúno', 'Ninguno ', 'Ninguno ', 'IPEMYT 310 Puerto Argentino ', 'Cuarto Año (Secundario) (Especialidad Preferida Economía y Gestión)', '....', '2023-08-16 08:12:11', '3173589161', 3, 0, '*', '*', 'No', '*', 'Con la Madre', 'Ninguno ', 'Tengo un familiar en la Institución', 'Valentin Farias \r\nNivel inicial  (PRIMO)', 'No', '*', 11, 2, '...'),
