INSERT INTO `comunicdocentes` (`id`, `idNivel`, `fecha`, `descripcion`, `texto`) VALUES
	(85, 3, '2024-11-06', 'Proyecto sociocomunitario de FVT “Empleo de la Tecnología en la adolescencia”', '<p>Proyecto sociocomunitario de FVT &ldquo;Empleo de la Tecnolog&iacute;a en la adolescencia&rdquo;. 4to a&ntilde;o D. Taller dirigido a</p>\n<p>los estudiantes de 1er a&ntilde;o D, 2do a&ntilde;o D y 3er a&ntilde;o D (8:50 a 10:10 hs). Antes y despu&eacute;s de esa actividad los</p>\n<p>estudiantes tienen clases en sus horarios habituales.</p>\n<p>Jornada Educar en Igualdad: Charla-Taller &ldquo;Prevenci&oacute;n integral y consumos problem&aacute;ticos de sustancias&rdquo;.</p>\n<p>5to a&ntilde;o Ay B (8:00 a 11:00 hs). 5to a&ntilde;o C y D (11:40 a 13:10 hs). Aulas de cada curso. Antes y despu&eacute;s de esa</p>\n<p>&nbsp;</p>\n<p>actividad los estudiantes tienen clases en sus horarios habituales.</p>'),
	(86, 3, '2024-11-07', 'Proyecto “Olimpiadas Matemáticas”', '<p>Proyecto &ldquo;Olimpiadas Matem&aacute;ticas&rdquo;. Cierre con todos los cursos (8:50 a 11:40 hs). Antes y despu&eacute;s de esa</p>\n<p>actividad los estudiantes tienen clases en sus horarios habituales.</p>'),
	(87, 3, '2024-11-08', 'Convivencia. 5to año', '<p>Convivencia. 5to a&ntilde;o, en el Club Germinar (7:20 a 22:30 hs).</p>\n<p>&nbsp;</p>'),
	(88, 3, NULL, '', ''),
	(89, 3, '2024-11-08', 'Torneo-Debate de Ciud. y Pol.', '<p>Torneo-Debate de Ciud. y Pol. &ldquo;La Argentina y sus deudas pendientes&rdquo;. 6to a&ntilde;o D, en el SUM del gimnasio (7:20 a 10:10 hs). Los estudiantes se retiran en su horario habitual</p>'),
	(90, 3, '2024-11-11', 'Charla con un ex combatiente de Malvinas. 5to año A, B y D', '<p>Charla con un ex combatiente de Malvinas. 5to a&ntilde;o A, B y D (8:50 a 11:40 hs). Comedor de estudiantes. Antes y despu&eacute;s de esa actividad los estudiantes tienen clases en sus horarios habituales.&nbsp;</p>'),
	(91, 3, '2024-11-13', 'Visita “Hospital Clínicas”', '<p>Visita &ldquo;Hospital Cl&iacute;nicas&rdquo;. 4to a&ntilde;o D (10:50 hs a 13:10hs). Antes y despu&eacute;s de esa actividad los estudiantes&nbsp; tienen clases en sus horarios habituales.</p>'),
	(92, 3, '2024-11-14', '“Empleo de la Tecnología en la adolescencia”.', '<p>Proyecto sociocomunitario de FVT &ldquo;Empleo de la Tecnolog&iacute;a en la adolescencia&rdquo;. 4to a&ntilde;o A. Taller dirigido a</p>\n<p>los estudiantes de 1er a&ntilde;o A, 2do a&ntilde;o A y 3er a&ntilde;o A (11:50 a 13:10 hs). Antes y despu&eacute;s de esa actividad los&nbsp;&nbsp;estudiantes tienen clases en sus horarios habituales.</p>'),
	(93, 3, '2024-11-15', 'Visita “Hospital Clínicas”. 4to año C', '<p>Visita &ldquo;Hospital Cl&iacute;nicas&rdquo;. 4to a&ntilde;o C (10:50 hs a 13:10hs). Antes y despu&eacute;s de esa actividad los estudiantes&nbsp;&nbsp;tienen clases en sus horarios habituales.</p>'),
	(94, 3, '2024-11-20', 'Acto conmemorativo por el Día de la Soberanía Nacional', '<p>Acto conmemorativo por el D&iacute;a de la Soberan&iacute;a Nacional (7:20 a 8:00 hs, horario aproximado).</p>');
