	(26586, 704, '2023-03-30', 6, 1, 'Teorico', 'Convivencia Social', 'Lectura Guiada- guia de actividad', ''),
	(26587, 715, '2023-03-30', 6, 1, 'Teorico', 'Convivencia Social', 'Lectura Guiada. Guia de Actividades', ''),
