	(32520, 793, '2023-06-01', 36, 2, 'Desarrollo', 'Past continuous. Affirmative, negative, interrogative forms and short answers. ', 'Junto a la docente, los jóvenes revisan los usos de dicho tiempo verbal. ', ''),
	(32521, 793, '2023-06-01', 37, 2, 'Desarrollo', 'Past continuous. All forms and uses. ', 'Junto a la docente, los jóvenes revisan las estructuras de dicho tiempo verbal. ', ''),
	(32522, 793, '2023-06-07', 38, 2, 'Desarrollo', 'Past continuous. Verb forme; ing forms. ', 'Completan un cuadro. Usan verbos dados. ', ''),
	(32523, 793, '2023-06-08', 39, 2, 'Evaluativa', 'Simple past. Past continuous. ', 'Trabjo práctico. En grupos leen textos relacionados con su orientación, las ciencias sociales. Luego responden un cuestionario. ', ''),
	(32524, 793, '2023-06-08', 40, 2, 'Evaluativa', 'Simple past. Past continuous. ', 'Traducen al español partes de los textos dados. ', ''),
	(32525, 793, '2023-06-14', 41, 2, 'Desarrollo', 'Simple past. Past continuous. Uses. ', 'Se explican correcciones y errores de la instancia evaluativa. ', ''),
	(32526, 793, '2023-06-15', 42, 2, 'Desarrollo', 'Simple past and past continuous. Linking words: when, while ', 'Combinan oraciones. Usan simple past y past continuous. ', ''),
	(32527, 793, '2023-06-15', 43, 2, 'Desarrollo', 'Simple past and past continuous. Linking words: when, while. ', 'Completan oraciones. Usan los verbos dados en simple past o past continuous. ', ''),
	(32528, 793, '2023-06-21', 44, 2, 'Desarrollo', 'Past continuous. All forms. ', 'Responden preguntas. Usan respuestas cortas.', ''),
	(32529, 793, '2023-06-22', 45, 2, 'Desarrollo', 'Past continuous vs. simple past. Contrast. ', 'Observan una figura. Describen los que sucedía en ella. ', ''),
	(32530, 793, '2023-06-22', 46, 2, 'Desarrollo', 'Past continuous. Simple past. "Ing" forms. ', 'Juego de roles. En pares, escriben un cuestionario acerca del hecho, responden sobre lo sucedido. ', ''),
	(32531, 793, '2023-06-28', 47, 2, 'Desarrollo', 'Past continuous. Simple past. Linking words. Complements of time. ', 'Escriben nuevamente oraciones, usando verbos dados en forma correcta. ', ''),
